const $=id=>document.getElementById(id);
const languageSelectIds=['live-language','lesson-language','train-language','library-language','catalog-language','clip-language'];
populateLanguageSelects(languageSelectIds);
setupLanguageSearch(languageSelectIds);
const gate=new RecognitionGate();
const video=$('camera'), canvas=$('overlay'), ctx=canvas.getContext('2d');
const trainingCanvas=$('train-preview'),trainingCtx=trainingCanvas.getContext('2d');
const CONNECTIONS=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];
let entries=[],models={},language='ASL',worker=null,stream=null,starting=false,active=false,busy=false,lastFrame=0,raf=0,runId=0;
let history=[],voices=[],recording=null,countdown=null,recordTimer=null,toastTimer=null,subtitleTimer=null;
let learning=null,worldUI=null;
let settings={autoSpeak:false,mirror:true,speechLanguage:'en',voice:'',rate:1,volume:1,threshold:.8,saveHistory:false};
try{settings={...settings,...JSON.parse(localStorage.getItem('sv-settings')||'{}')};language=localStorage.getItem('sv-language')||'ASL';if(!isLanguage(language))language='ASL';if(settings.saveHistory)history=JSON.parse(localStorage.getItem('sv-history')||'[]').slice(-100);}catch{}
// Speech never starts automatically on reload.
settings.autoSpeak=false;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function persistSettings(){try{localStorage.setItem('sv-settings',JSON.stringify(settings));localStorage.setItem('sv-language',language);}catch{toast('Settings could not be saved in this browser.');}}
async function persistEntries(){try{await saveEntries(entries);return true;}catch{toast('Recordings could not be saved. Export them now to keep a backup.');return false;}}
function persistHistory(){try{if(settings.saveHistory)localStorage.setItem('sv-history',JSON.stringify(history));else localStorage.removeItem('sv-history');}catch{toast('Conversation history could not be saved.');}}
function confirmAction(title,body){return new Promise(resolve=>{const d=$('confirm-dialog');$('confirm-title').textContent=title;$('confirm-body').textContent=body;let settled=false;const close=value=>{if(settled)return;settled=true;d.close();$('confirm-yes').onclick=null;$('confirm-no').onclick=null;d.oncancel=null;resolve(value);};$('confirm-yes').onclick=()=>close(true);$('confirm-no').onclick=()=>close(false);d.oncancel=e=>{e.preventDefault();close(false);};d.showModal();});}
function navigate(view){if(!['live','learn','train','library','settings','guide','world'].includes(view))view='live';if(view!=='train'&&(recording||countdown))cancelRecording();document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!=='view-'+view);document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===view));location.hash=view;learning?.onView(view);worldUI?.onView(view);}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'live');

function updateLanguage(){document.querySelectorAll('[data-language]').forEach(b=>b.classList.toggle('selected',b.dataset.language===language));const classes=models[language]?.classes.filter(c=>c.id!==NEUTRAL)||[];$('model-note').replaceChildren();const text=document.createElement('span');text.textContent=language==='ASL'?`ASL starter: “I love you” · ${classes.length} personal sign(s) trained. Other words need recordings.`:`${languageName(language)}: ${classes.length} personal sign(s) trained. ${classes.length?'Only your trained vocabulary is supported.':'Record verified examples to enable recognition.'}`;$('model-note').append(text);const b=document.createElement('a');b.href='#train';b.textContent='Teach a sign ↗';$('model-note').append(b);$('prediction').textContent='Ready when you are';$('prediction-detail').textContent=active?'Show a supported sign.':'Enable the camera to begin.';$('match-score').textContent='—';$('live-language').value=language;$('train-language').value=language;$('library-language').value=language;worker?.postMessage({type:'profile',model:models[language]||null});gate.reset();$('subtitle').hidden=true;renderRecordOptions();renderLibrary();persistSettings();}
$('live-language').onchange=()=>{if(recording||countdown)cancelRecording();language=$('live-language').value;updateLanguage();};
document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>{if(recording||countdown)cancelRecording();language=b.dataset.language;updateLanguage();});

function setCameraStatus(text,on=false){$('camera-status').textContent=text;$('camera-dot').classList.toggle('on',on);}
function disposeCamera(){learning?.onCameraStop();runId++;active=false;starting=false;cancelAnimationFrame(raf);worker?.terminate();worker=null;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;video.style.display='none';$('camera-empty').hidden=false;$('tracking-chip').hidden=true;$('subtitle').hidden=true;$('stop-camera').disabled=true;$('start-camera').disabled=false;$('start-camera').textContent='Enable camera ↗';canvas.width=canvas.width;trainingCtx.clearRect(0,0,trainingCanvas.width,trainingCanvas.height);busy=false;gate.reset();cancelRecording();setCameraStatus('Camera is off');$('tracking-detail').textContent='Two-hand tracking · local inference';$('fps').textContent='LOCAL PROCESSING';}
async function startCamera(){
  if(starting||active)return;
  if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){toast('Open the app over HTTPS or at http://localhost:3000 to use your camera.');return;}
  starting=true;const id=++runId;$('start-camera').disabled=true;$('start-camera').textContent='Loading tracking model…';setCameraStatus('Preparing on-device model');
  try{
    worker=new Worker(new URL('./vision.worker.js',import.meta.url));
    await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Model loading timed out. Check your connection and retry.')),60000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(timeout);resolve();}else if(data.type==='error'){clearTimeout(timeout);reject(Error(data.message));}};worker.onerror=e=>{clearTimeout(timeout);reject(Error(e.message||'This browser could not initialize the tracking worker.'));};worker.postMessage({type:'init'});});
    if(id!==runId)return;
    worker.onmessage=onWorkerMessage;worker.onerror=e=>{toast('Tracking stopped: '+(e.message||'worker error'));disposeCamera();};worker.postMessage({type:'profile',model:models[language]||null});
    setCameraStatus('Requesting camera access');$('start-camera').textContent='Allow camera access…';
    const media=await navigator.mediaDevices.getUserMedia({audio:false,video:{width:{ideal:960},height:{ideal:540},frameRate:{ideal:24},facingMode:'user'}});
    if(id!==runId){media.getTracks().forEach(t=>t.stop());return;}
    stream=media;video.srcObject=stream;await video.play();
    if(id!==runId)return;
    stream.getVideoTracks()[0].onended=()=>{toast('The camera disconnected. Enable it again to reconnect.');disposeCamera();};
    active=true;starting=false;$('camera-empty').hidden=true;video.style.display='block';$('tracking-chip').hidden=false;$('stop-camera').disabled=false;setCameraStatus('Camera is live',true);lastFrame=0;raf=requestAnimationFrame(pumpFrame);
  }catch(error){if(id!==runId)return;disposeCamera();const messages={NotAllowedError:'Camera access was denied. Allow camera access in your browser’s site settings, then retry.',NotFoundError:'No camera was found. Connect a webcam and retry.',NotReadableError:'Camera is busy. Close other camera apps and retry.'};toast(messages[error.name]||error.message);setCameraStatus('Camera setup failed');}
}
async function pumpFrame(now){if(!active)return;raf=requestAnimationFrame(pumpFrame);if(busy||now-lastFrame<1000/CONFIG.frameRate||video.readyState<2)return;lastFrame=now;busy=true;const id=runId;try{const bitmap=await createImageBitmap(video);if(id!==runId||!worker){bitmap.close();busy=false;return;}worker.postMessage({type:'frame',bitmap,timestamp:performance.now()},[bitmap]);}catch(error){busy=false;toast('Frame capture failed: '+error.message);disposeCamera();}}
function onWorkerMessage({data}){
  busy=false;if(!active)return;
  if(data.type==='frame-error'){toast('Tracking failed: '+data.message);disposeCamera();return;}
  if(data.type!=='result')return;
  const {result,feature,timestamp,latency}=data;
  drawHands(result.landmarks);learning?.onCameraFrame(video,canvas,settings.mirror);if(!$('view-train').hidden){trainingCtx.save();if(settings.mirror){trainingCtx.translate(trainingCanvas.width,0);trainingCtx.scale(-1,1);}trainingCtx.drawImage(video,0,0,trainingCanvas.width,trainingCanvas.height);trainingCtx.drawImage(canvas,0,0,trainingCanvas.width,trainingCanvas.height);trainingCtx.restore();}$('tracking-chip').textContent=result.landmarks.length?`${result.landmarks.length} hand${result.landmarks.length>1?'s':''} tracked`:'Waiting for hands';$('fps').textContent=`${Math.round(latency)} MS INFERENCE`;$('tracking-detail').textContent=result.landmarks.length?'Hand landmarks active · video stays local':'Keep your hands visible in good lighting';
  if(recording){recording.frames.push(feature);$('record-progress').style.width=Math.min(100,(timestamp-recording.started)/CONFIG.recordingMs*100)+'%';return;}
  if(countdown)return;
  let prediction=data.prediction;
  if(!prediction && language==='ASL'){
    const candidates=result.gestures.flat().filter(g=>g.categoryName==='ILoveYou'&&g.score>=settings.threshold).sort((a,b)=>b.score-a.score);
    if(candidates.length)prediction={id:'builtin-ily',label:'I love you',speech:'I love you',score:candidates[0].score,source:'Pretrained ASL starter'};
  }
  if(prediction){$('prediction').textContent=prediction.label;$('prediction-detail').textContent=prediction.source+' · hold briefly to accept';$('match-score').textContent=Math.round(prediction.score*100)+'%';}
  else{$('prediction').textContent=result.landmarks.length?'No supported match':'Ready when you are';$('prediction-detail').textContent=language!=='ASL'&&!models[language]?.classes.length?'Teach verified signs to build this language’s vocabulary.':'Unknown signs remain silent.';$('match-score').textContent='—';}
  const accepted=gate.update(prediction,timestamp);if(accepted)acceptSign(accepted);
}
function drawHands(hands){canvas.width=video.videoWidth||960;canvas.height=video.videoHeight||540;ctx.clearRect(0,0,canvas.width,canvas.height);for(const [i,hand] of hands.entries()){ctx.strokeStyle=i?'#eab58e':'#b6f2bc';ctx.fillStyle=i?'#eab58e':'#d4f9d6';ctx.lineWidth=2;for(const [a,b] of CONNECTIONS){ctx.beginPath();ctx.moveTo(hand[a].x*canvas.width,hand[a].y*canvas.height);ctx.lineTo(hand[b].x*canvas.width,hand[b].y*canvas.height);ctx.stroke();}for(const p of hand){ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,3,0,Math.PI*2);ctx.fill();}}}
$('start-camera').onclick=startCamera;$('train-start-camera').onclick=startCamera;$('stop-camera').onclick=disposeCamera;
function mirror(){ $('camera-stage').classList.toggle('mirror',settings.mirror);$('mirror-toggle').textContent=settings.mirror?'↔ Mirror on':'↔ Mirror off';$('mirror-toggle').setAttribute('aria-pressed',settings.mirror);}
$('mirror-toggle').onclick=()=>{settings.mirror=!settings.mirror;mirror();persistSettings();};mirror();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&(active||starting)){disposeCamera();toast('Camera stopped when this tab was hidden. Enable it to resume.');}});window.addEventListener('pagehide',()=>{disposeCamera();window.speechSynthesis?.cancel();});

function acceptSign(p){const item={id:crypto.randomUUID(),label:p.label,text:p.speech,language,time:new Date().toISOString(),source:p.source};history.push(item);history=history.slice(-100);$('sentence').value=[$('sentence').value.trim(),p.speech].filter(Boolean).join(' ');$('subtitle').textContent=p.label;$('subtitle').hidden=false;clearTimeout(subtitleTimer);subtitleTimer=setTimeout(()=>$('subtitle').hidden=true,3500);renderHistory();persistHistory();learning?.onRecognized(p);if(settings.autoSpeak)speakText(p.speech);}
function renderHistory(){const feed=$('transcript-feed');if(!history.length){feed.innerHTML='<div class="transcript-empty"><span aria-hidden="true">“</span><h3>Every sign has a story.</h3><p>Recognized signs appear here.<br>Edit them before speaking.</p></div>';}else{feed.replaceChildren();history.forEach(item=>{const div=document.createElement('div');div.className='transcript-item';const time=document.createElement('time');time.textContent=new Date(item.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+' · '+item.language;const p=document.createElement('p');p.textContent=item.text;const b=document.createElement('button');b.textContent='Replay ◖))';b.onclick=()=>speakText(item.text);div.append(time,p,b);feed.append(div);});feed.scrollTop=feed.scrollHeight;}$('word-count').textContent=history.length+' sign'+(history.length===1?'':'s');}
function speakText(text){text=text.trim();if(!text){toast('Your message is empty. Sign a supported word or type a message.');return;}if(!window.speechSynthesis){toast('Speech synthesis is not supported in this browser.');return;}const voice=voices.find(v=>v.voiceURI===settings.voice);if(settings.speechLanguage!=='en'&&!voice?.lang.toLowerCase().startsWith(settings.speechLanguage.toLowerCase())){toast('No compatible voice is selected. Install a system voice for this spoken language or choose an available one.');return;}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text.slice(0,2000));utterance.lang=voice?.lang||(settings.speechLanguage==='en'?'en-US':settings.speechLanguage);if(voice)utterance.voice=voice;utterance.rate=Number(settings.rate);utterance.volume=Number(settings.volume);utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('Speech could not play: '+e.error);};window.speechSynthesis.speak(utterance);}
function refreshVoices(){voices=window.speechSynthesis?.getVoices()||[];const languageSelect=$('speech-language'),names=new Intl.DisplayNames(['en'],{type:'language'});languageSelect.replaceChildren();for(const code of [...new Set(['en','hi',settings.speechLanguage,...voices.map(v=>v.lang.split(/[-_]/)[0].toLowerCase())])].sort()){const o=document.createElement('option');o.value=code;try{o.textContent=names.of(code);}catch{o.textContent=code;}languageSelect.append(o);}languageSelect.value=settings.speechLanguage;const filtered=voices.filter(v=>v.lang.toLowerCase().startsWith(settings.speechLanguage.toLowerCase()));$('voice').replaceChildren();for(const v of filtered){const opt=document.createElement('option');opt.value=v.voiceURI;opt.textContent=`${v.name} (${v.lang})${v.localService?' · device':''}`;$('voice').append(opt);}if(!filtered.length){const o=document.createElement('option');o.value='';o.textContent=settings.speechLanguage==='en'?'System default voice':'No voice available for this language';$('voice').append(o);settings.voice='';}else if(!filtered.some(v=>v.voiceURI===settings.voice)){settings.voice=filtered[0].voiceURI;}$('voice').value=settings.voice;$('voice-note').textContent=filtered.length?'Device voices vary. A voice marked “device” reports local synthesis.':'Voice availability depends on your browser and installed system voices.';}
if(window.speechSynthesis)window.speechSynthesis.onvoiceschanged=refreshVoices;
$('speak').onclick=()=>speakText($('sentence').value);$('test-voice').onclick=()=>speakText(settings.speechLanguage==='hi'?'नमस्ते, यह मेरी आवाज़ है।':'Hello. This is my SignVoice.');$('stop-speech').onclick=()=>window.speechSynthesis?.cancel();$('clear-message').onclick=()=>{$('sentence').value='';};$('clear-history').onclick=async()=>{if(history.length&&await confirmAction('Clear conversation?','This removes your conversation history from this browser.')){history=[];renderHistory();persistHistory();}};
$('auto-speak').onchange=e=>{settings.autoSpeak=e.target.checked;persistSettings();if(settings.autoSpeak)toast('Auto-speak enabled. Uncertain predictions can still be wrong; review matches carefully.');};
for(const id of ['rate','volume','threshold']){$(id).value=settings[id];$(id).oninput=e=>{settings[id]=Number(e.target.value);updateSettingLabels();persistSettings();};}
function updateSettingLabels(){$('rate-value').textContent=Number(settings.rate).toFixed(1)+'×';$('threshold-value').textContent=Math.round(settings.threshold*100)+'%';}
$('speech-language').value=settings.speechLanguage;$('speech-language').onchange=e=>{settings.speechLanguage=e.target.value;refreshVoices();persistSettings();};$('voice').onchange=e=>{settings.voice=e.target.value;persistSettings();};$('save-history').checked=settings.saveHistory;$('save-history').onchange=e=>{settings.saveHistory=e.target.checked;persistSettings();persistHistory();};updateSettingLabels();refreshVoices();

function renderRecordOptions(){const lang=$('train-language').value,selection=$('record-sign').value;$('record-sign').replaceChildren();const relevant=entries.filter(e=>e.language===lang);if(!relevant.length){const o=document.createElement('option');o.value='';o.textContent='Create a sign or background class first';$('record-sign').append(o);}for(const e of relevant){const o=document.createElement('option');o.value=e.id;o.textContent=`${e.label} · ${e.samples.length}/${CONFIG.minSamples} examples`;$('record-sign').append(o);}if(relevant.some(e=>e.id===selection))$('record-sign').value=selection;renderSamples();}
function selectedEntry(){return entries.find(e=>e.id===$('record-sign').value&&e.language===$('train-language').value);}
function renderSamples(){const entry=selectedEntry();$('sample-list').replaceChildren();if(!entry)return;entry.samples.forEach((s,i)=>{const row=document.createElement('div');row.className='sample-row';const txt=document.createElement('span');txt.textContent=`Example ${i+1} · ${s.frames.length} frames · ${s.session}`;const b=document.createElement('button');b.className='text-button';b.textContent='Remove ×';b.onclick=async()=>{if(recording||countdown){toast('Finish or cancel the recording first.');return;}entry.samples=entry.samples.filter(x=>x.id!==s.id);invalidate(entry.language);await persistEntries();renderRecordOptions();renderLibrary();toast('Example removed. Retrain this language to update recognition.');};row.append(txt,b);$('sample-list').append(row);});}
function invalidate(lang){delete models[lang];if(lang===language){worker?.postMessage({type:'profile',model:null});gate.reset();}updateModelNoteOnly();}
function updateModelNoteOnly(){const n=models[language]?.classes.filter(c=>c.id!==NEUTRAL).length||0;$('model-note').firstChild&&( $('model-note').firstChild.textContent=language==='ASL'?`ASL starter: “I love you” · ${n} personal sign(s) trained. Other words need recordings.`:`${languageName(language)}: ${n} personal sign(s) trained. ${n?'Only trained signs are supported.':'Record verified examples to enable recognition.'}`);}
$('train-language').onchange=()=>{cancelRecording();renderRecordOptions();};$('record-sign').onchange=()=>{cancelRecording();renderSamples();};
$('add-sign').onclick=async()=>{const label=$('sign-label').value.trim(),speech=$('sign-speech').value.trim(),lang=$('train-language').value;if(!label||!speech){toast('Enter a display label and the words to speak.');return;}if(entries.length>=500){toast('This device supports up to 500 total personal entries. Export and remove unused entries.');return;}if(entries.filter(e=>e.language===lang).length>=(entries.some(e=>e.language===lang&&e.id===NEUTRAL)?30:29)){toast('This browser prototype supports up to 30 entries per language.');return;}if(entries.some(e=>e.language===lang&&e.label.toLowerCase()===label.toLowerCase())){toast('That label already exists. Record more examples into the existing sign.');return;}const entry={id:crypto.randomUUID(),language:lang,label,speech,kind:$('sign-kind').value,samples:[]};entries.push(entry);await persistEntries();renderRecordOptions();$('record-sign').value=entry.id;renderSamples();renderLibrary();$('sign-label').value='';$('sign-speech').value='';toast('Sign created. Record at least three examples.');};
$('add-neutral').onclick=async()=>{const lang=$('train-language').value;let e=entries.find(e=>e.language===lang&&e.id===NEUTRAL);if(!e){if(entries.length>=500||entries.filter(e=>e.language===lang).length>=30){toast('Remove an unused entry to make room for background examples.');return;}e={id:NEUTRAL,language:lang,label:'Neutral / background',speech:'',kind:'neutral',samples:[]};entries.push(e);await persistEntries();}renderRecordOptions();$('record-sign').value=e.id;renderSamples();toast('Record resting hands and varied non-sign movements as background.');};
function cancelRecording(){clearInterval(countdown);countdown=null;clearTimeout(recordTimer);recordTimer=null;recording=null;$('record').disabled=false;$('cancel-record').hidden=true;$('record-progress').style.width='0%';$('record-state').textContent='Choose a sign to record';gate.reset();}
$('cancel-record').onclick=cancelRecording;
$('record').onclick=()=>{
  const e=selectedEntry();if(!active){toast('Enable the camera in Live interpreter, then return here to record.');return;}if(!e){toast('Create or select a sign first.');return;}if(e.samples.length>=CONFIG.maxSamples){toast('Maximum 12 examples per sign. Remove one to record a replacement.');return;}const signer=$('signer').value.trim(),session=$('session').value.trim();if(!signer||!session){toast('Enter a signer ID and a recording session ID.');return;}
  let seconds=3;$('record').disabled=true;$('cancel-record').hidden=false;$('record-state').textContent=`Get ready… ${seconds}`;
  countdown=setInterval(()=>{seconds--;if(seconds>0){$('record-state').textContent=`Get ready… ${seconds}`;return;}clearInterval(countdown);countdown=null;recording={entryId:e.id,language:e.language,frames:[],started:performance.now(),signer,session};$('record-state').textContent='Signing… keep both hands visible';recordTimer=setTimeout(finishRecording,CONFIG.recordingMs);},1000);
};
async function finishRecording(){if(!recording)return;const take=recording;const e=entries.find(x=>x.id===take.entryId&&x.language===take.language);cancelRecording();const visible=take.frames.filter(f=>f[65]||f[131]).length;if(!e||take.frames.length<18){toast('Too few frames. Your device was busy; try recording again.');return;}if(e.kind!=='neutral'&&visible/take.frames.length<.75){toast('Hands were missing for too much of the recording. Keep the full sign visible and retry.');return;}e.samples.push({id:crypto.randomUUID(),signer:take.signer,session:take.session,createdAt:new Date().toISOString(),frames:take.frames});invalidate(e.language);await persistEntries();renderRecordOptions();renderLibrary();$('record-state').textContent=`Saved example ${e.samples.length}`;toast('Example captured. Vary the timing or position for the next take.');}
$('train-model').onclick=()=>{if(recording||countdown){toast('Finish recording before training.');return;}const lang=$('train-language').value;const neutral=entries.find(e=>e.language===lang&&e.id===NEUTRAL);const signs=entries.filter(e=>e.language===lang&&e.id!==NEUTRAL&&e.samples.length>=3);if(!neutral||neutral.samples.length<3||!signs.length){toast('Record 3 examples for at least one sign and 3 examples for neutral/background.');return;}models[lang]=trainProfile(entries,lang);const skipped=entries.filter(e=>e.language===lang&&e.samples.length<3).length;$('training-status').textContent=`Trained ${signs.length} sign(s) and background for ${lang}. ${skipped?skipped+' unfinished sign(s) skipped. ':''}Test with new examples; no accuracy has been measured.`;if(lang===language){worker?.postMessage({type:'profile',model:models[lang]});gate.reset();}updateModelNoteOnly();renderLibrary();toast(`${lang} personal model trained. Try your signs in Live interpreter.`);};

function renderPersonalLibrary(){const lang=$('library-language').value,container=$('library-items');container.replaceChildren();if(lang==='ASL'){const card=document.createElement('article');card.className='sign-card';card.innerHTML='<span class="badge">PRETRAINED STARTER</span><h3>I love you</h3><p>One ASL handshape supported by MediaPipe’s trained gesture classifier. Hold briefly to accept.</p><div class="caption">Thumb, index and little finger extended.</div>';container.append(card);}const relevant=entries.filter(e=>e.language===lang);for(const e of relevant){const card=document.createElement('article');card.className='sign-card';const badge=document.createElement('span');badge.className='badge';badge.textContent=models[lang]?.classes.some(c=>c.id===e.id)?'PERSONAL MODEL TRAINED':'NEEDS TRAINING';const title=document.createElement('h3');title.textContent=e.label;const p=document.createElement('p');p.textContent=e.speech||'Background examples are never spoken.';const meta=document.createElement('div');meta.className='caption';meta.textContent=`${e.samples.length} real recordings · ${e.kind}`;const actions=document.createElement('div');actions.className='actions';const record=document.createElement('button');record.className='text-button';record.textContent='Add examples ↗';record.onclick=()=>{$('train-language').value=lang;renderRecordOptions();$('record-sign').value=e.id;renderSamples();navigate('train');};const remove=document.createElement('button');remove.className='text-button';remove.textContent='Delete';remove.onclick=async()=>{if(await confirmAction('Delete this sign?',`Remove “${e.label}” and all its recorded examples?`)){cancelRecording();entries=entries.filter(x=>!(x.id===e.id&&x.language===lang));invalidate(lang);await persistEntries();renderRecordOptions();renderLibrary();}};actions.append(record,remove);card.append(badge,title,p,meta,actions);container.append(card);}if(!relevant.length&&lang!=='ASL'){const empty=document.createElement('div');empty.className='library-empty';const title=document.createElement('h2');title.textContent='Your '+languageName(lang)+' vocabulary starts here.';const p=document.createElement('p');p.textContent='No pretrained translator is bundled for this profile. Teach verified isolated signs with real camera examples.';empty.append(title,p);container.append(empty);}}
function renderLibrary(){renderPersonalLibrary();learning?.refreshRecognition();}
$('library-language').onchange=renderLibrary;
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-dataset').onclick=()=>download('signvoice-recordings.json',JSON.stringify({schemaVersion:1,featureVersion:CONFIG.featureVersion,exportedAt:new Date().toISOString(),entries},null,2));
$('export-transcript').onclick=()=>{if(!history.length){toast('No recognized signs to export yet.');return;}download('signvoice-conversation.txt',history.map(i=>`[${new Date(i.time).toLocaleString()}] ${i.language}: ${i.text}`).join('\n'),'text/plain');};
$('import-dataset').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>30*1024*1024){toast('Choose a recordings JSON file smaller than 30 MB.');return;}try{const data=validateDataset(JSON.parse(await file.text()));if(await confirmAction('Replace your recordings?',`Import ${data.entries.length} entries? Current recordings will be replaced. Export a backup first if you need them.`)){cancelRecording();entries=data.entries;models={};for(const lang of [...new Set(entries.map(e=>e.language))]){const model=trainProfile(entries,lang);if(model.classes.some(c=>c.id===NEUTRAL)&&model.classes.some(c=>c.id!==NEUTRAL))models[lang]=model;}await persistEntries();updateLanguage();toast('Recordings imported. Eligible models trained from their real examples.');}}catch(error){toast('Import failed: '+error.message);}};
$('delete-data').onclick=async()=>{if(await confirmAction('Delete all local data?','This removes saved sign recordings, personal models, imported references, lesson clips, saved practice phrases, learning progress and conversation history from this browser. Export a backup if you need it.')){cancelRecording();entries=[];models={};history=[];$('sentence').value='';await persistEntries();try{await learning?.clearImported();await worldUI?.clear();persistHistory();updateLanguage();renderHistory();toast('Local recordings, references, lesson clips, progress and conversation history deleted.');}catch(error){persistHistory();updateLanguage();renderHistory();toast('Some local learning data could not be removed. Retry deletion or clear site data in your browser.');}}};
async function init(){try{const loaded=await loadEntries();validateDataset({schemaVersion:1,featureVersion:CONFIG.featureVersion,entries:loaded});entries=loaded;for(const lang of [...new Set(entries.map(e=>e.language))]){const model=trainProfile(entries,lang);if(model.classes.some(c=>c.id===NEUTRAL)&&model.classes.some(c=>c.id!==NEUTRAL))models[lang]=model;}}catch{toast('Saved recordings could not be loaded. You can still use the camera and export new recordings.');}const sessionId=new Date().toISOString().slice(0,10)+'-'+Math.random().toString(36).slice(2,5);$('session').value=sessionId;updateLanguage();renderHistory();}
learning=createLearningUI({getEntries:()=>entries,getModels:()=>models,navigate,toast,download,confirmAction,startCamera,stopCamera:disposeCamera,
  showWorld(lang){worldUI?.selectLanguage(lang);},
  setLanguage(lang){if(!isLanguage(lang))return;if(lang!==language){cancelRecording();language=lang;updateLanguage();}},
  trainSign(lang,label){cancelRecording();$('train-language').value=lang;renderRecordOptions();const existing=entries.find(e=>e.language===lang&&e.label.toLowerCase()===label.toLowerCase());if(existing){$('record-sign').value=existing.id;renderSamples();}else{$('sign-label').value=label.slice(0,80);$('sign-speech').value=label.slice(0,200);}navigate('train');}
});
worldUI=createWorldUI({navigate,toast,download,confirmAction,practice(lang){learning.selectLanguage(lang);language=lang;updateLanguage();navigate('learn');},train(lang,label=''){language=lang;updateLanguage();$('sign-label').value=label.slice(0,80);$('sign-speech').value=label.slice(0,200);navigate('train');}});
setupOffline({toast});
init();
